import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: View cart.
*/
export type ViewCart = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class ViewCartBuilder {

    private viewCart: ViewCart = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : ViewCartBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : ViewCartBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ViewCartBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ViewCartBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : ViewCart {
        if(this.cart) {
            this.viewCart.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.viewCart.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.viewCart.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.viewCart.events.push(this.partyIdentification);
        }

        return this.viewCart;
    }
}
